$roster$::jsonb) as x(
  roster_id integer,slug text,name text,age integer,gender text,pronouns text,background text,classification text,
  district_slug text,occupation text,work_slug text,work_activity text,leisure_slug text,leisure_activity text,
  evening_slug text,weekend_slug text,shift_kind text,spice_level integer,biography text,appearance text,
  interests text[],traits text[],quirks text,story_hook text,dialogue_tone text,opening_line text,circle_slugs text[],romance_style text
);

-- Character template slugs are global. Keep Vespormoor's Camille distinct
-- from Port Vervelle's existing Camille Laurent while preserving her name.
update kivelle_vespormoor_roster
set slug='camille-laurent-vespormoor'
where roster_id=9;

update kivelle_vespormoor_roster
set circle_slugs=array_replace(circle_slugs,'camille-laurent','camille-laurent-vespormoor')
where 'camille-laurent'=any(circle_slugs);

-- Display names are not identities and may legitimately repeat across worlds.
-- Stable slugs, template IDs, and world presence remain unique.
alter table public.together_character_templates
  drop constraint if exists together_character_templates_name_key;

insert into public.together_character_templates(
  id,name,slug,public_handle,age,occupation,biography,creator_id,current_published_version,
  published,lifecycle_status,visibility,relationship_goal,connection_config,spice_level,
  character_role,can_be_selected,can_be_romanced,discovery_metadata,first_meeting,updated_at
)
select
  ('22000000-0000-4000-8010-'||lpad(roster_id::text,12,'0'))::uuid,
  name,slug,slug,age,occupation,biography,null,1,true,'published','public','either',
  jsonb_build_object(
    'spiceLevel',spice_level,
    'romanticPace',case spice_level when 1 then .3 when 2 then .58 else .82 end,
    'affection',case spice_level when 1 then .46 when 2 then .68 else .8 end,
    'initiative',case spice_level when 1 then .36 when 2 then .64 else .87 end,
    'romanceStyle',romance_style
  ),
  spice_level,'primary_companion',true,true,
  jsonb_build_object(
    'summary',biography,'traits',to_jsonb(traits),'goals',jsonb_build_array('Dating','Friendship','Stories'),
    'featured',roster_id in(1,2,3,8,15,22,34,40),'new',true,'gender',gender,'pronouns',pronouns,
    'background',background,'classification',classification,'species','human-presenting',
    'residentWorldSlug','vespormoor','districtSlug',district_slug,'primaryLocationSlug',work_slug,
    'portraitStatus','pending','portraitSlotKey','vespormoor-character-'||slug,
    'portraitFocalPosition','top','storyHook',story_hook,
    'romancePreferences',jsonb_build_object('available',true,'playerInclusive',true,'style',romance_style),
    'initialRelationshipState','stranger'
  ),
  jsonb_build_object(
    'world_id','10000000-0000-4000-8000-000000000010'::uuid,'location_id',meeting.id,
    'title','Meet '||split_part(name,' ',1),'setup',name||' is '||work_activity||' when you meet.',
    'companion_activity',work_activity,'mood',case when spice_level=1 then 'quietly curious' when spice_level=2 then 'warmly curious' else 'confidently interested' end,
    'opening_line',opening_line,
    'suggested_prompts',jsonb_build_array('What are you working on?','What should I know about this place?','Who do you trust around here?')
  ),now()
from kivelle_vespormoor_roster roster
join (
  select id,world_id,slug as location_slug from public.together_locations
) meeting on meeting.world_id='10000000-0000-4000-8000-000000000010' and meeting.location_slug=roster.work_slug
on conflict(id) do update set
  name=excluded.name,slug=excluded.slug,public_handle=excluded.public_handle,age=excluded.age,
  occupation=excluded.occupation,biography=excluded.biography,current_published_version=1,
  published=true,lifecycle_status='published',visibility='public',relationship_goal='either',
  connection_config=excluded.connection_config,spice_level=excluded.spice_level,
  character_role='primary_companion',can_be_selected=true,can_be_romanced=true,
  discovery_metadata=excluded.discovery_metadata,first_meeting=excluded.first_meeting,updated_at=now();

