select
  ('23000000-0000-4000-8010-'||lpad(roster_id::text,12,'0'))::uuid,
  ('22000000-0000-4000-8010-'||lpad(roster_id::text,12,'0'))::uuid,1,pronouns,
  jsonb_build_object(
    'warmth',case when 'warm'=any(traits) or 'gentle'=any(traits) or 'compassionate'=any(traits) then .86 else .66 end,
