  ),
  array['fictional adult','mutual consent','independent point of view','respect user boundaries','do not reveal Veiled knowledge without trust and context','do not fetishize background or unusual ability','remain essentially human-presenting'],
  to_jsonb(circle_slugs),null,
  jsonb_build_object('goal','either','spiceLevel',spice_level,'romanticEnergy',romance_style,'pace',case spice_level when 1 then 'slow' when 2 then 'organic' else 'confident' end,'initialStage','stranger'),
  jsonb_build_object(
