    'occupation',jsonb_build_object('title',occupation,'workPattern',shift_kind,'primaryLocationSlug',work_slug,'activityVariants',jsonb_build_array(work_activity)),
    'sleep',case when shift_kind in('night','overnight') then jsonb_build_object('preferredBedtime',jsonb_build_object('startMinute',240,'endMinute',360),'preferredWakeTime',jsonb_build_object('startMinute',720,'endMinute',840),'variabilityMinutes',45,'weekendShiftMinutes',45) else jsonb_build_object('preferredBedtime',jsonb_build_object('startMinute',1320,'endMinute',60),'preferredWakeTime',jsonb_build_object('startMinute',360,'endMinute',510),'variabilityMinutes',35,'weekendShiftMinutes',60) end,
    'lifestyle',jsonb_build_object('social',case when traits&&array['reserved','private','quiet','solitary','shy']::text[] then .4 else .72 end,'spontaneous',case spice_level when 1 then .45 when 2 then .64 else .8 end,'creativity',.8,'modernLife',1),
    'interests',to_jsonb(interests),'publicLocationSlugs',to_jsonb(array[work_slug,leisure_slug,evening_slug,weekend_slug]),
    'publicScheduleNotes',jsonb_build_array(work_activity,leisure_activity,'Evenings around '||evening_slug,'Weekend variation around '||weekend_slug),
