    'appearance',appearance,'occupation',occupation,'interests',to_jsonb(interests),'quirks',quirks,
    'storyHook',story_hook,'dialogueTone',dialogue_tone,'socialCircle',to_jsonb(circle_slugs),
    'romanceStyle',romance_style,'initialRelationshipState','stranger',
    'worldKnowledge',jsonb_build_object('homeDistrict',district_slug,'familiarity','local','veiledDisclosure','trust_and_story_gated'),
    'worldBehavior',jsonb_build_array('Live a contemporary everyday life inside Vespormoor.','Do not force supernatural exposition.','Know close contacts directly, district acquaintances generally, and distant circles mainly by public reputation or rumor.','Never claim monster anatomy or transformation.'),
    'values',jsonb_build_object('autonomy',.96,'mutualRespect',.96,'privacy',.94),'fictional',true
  ),
  '[]'::jsonb,now(),now()
from kivelle_vespormoor_roster roster
join (
  select id,world_id,slug as location_slug from public.together_locations
) home on home.world_id='10000000-0000-4000-8000-000000000010' and home.location_slug=roster.district_slug
on conflict(id) do update set
  pronouns=excluded.pronouns,personality_config=excluded.personality_config,values_config=excluded.values_config,
  interests=excluded.interests,communication_style=excluded.communication_style,appearance_config=excluded.appearance_config,
  visual_identity=excluded.visual_identity,voice_config=excluded.voice_config,boundaries=excluded.boundaries,
  default_social_graph=excluded.default_social_graph,portrait_asset_key=null,
  relationship_config=excluded.relationship_config,life_config=excluded.life_config,character_bible=excluded.character_bible,
  appearance_candidates='[]'::jsonb,published_at=excluded.published_at,updated_at=now();

insert into public.together_character_world_presence(
  character_version_id,world_id,presence_type,home_location_id,familiarity,visited_count,metadata
)
select
  ('23000000-0000-4000-8010-'||lpad(roster_id::text,12,'0'))::uuid,
  '10000000-0000-4000-8000-000000000010'::uuid,'resident',home.id,1,1,
  jsonb_build_object('source','vespormoor_character_roster','residentWorldSlug','vespormoor','homeDistrictSlug',district_slug,
    'workLocationSlug',work_slug,'classification',classification,'portraitStatus','pending','portraitSlotKey','vespormoor-character-'||slug,
    'authored',true,'dynamicSchedule',true,'scheduleProfile','vespormoor_launch')
from kivelle_vespormoor_roster roster
join (
  select id,world_id,slug as location_slug from public.together_locations
) home on home.world_id='10000000-0000-4000-8000-000000000010' and home.location_slug=roster.district_slug
on conflict(character_version_id,world_id) do update set presence_type='resident',home_location_id=excluded.home_location_id,
  familiarity=1,metadata=excluded.metadata,updated_at=now();

-- The generic virtual-home trigger predates Vespormoor and otherwise falls
-- through to Juniper's apartment language. Re-author only this roster's auto
-- homes as modern private residences grounded in their actual district.
update public.together_character_homes home
set
  residence_type=case district.slug
    when 'old-vesper' then 'warm modern flat inside a restored Old Vesper building'
    when 'vesper-heights' then 'private contemporary rooms in a wooded Heights residence'
    when 'lakeward' then 'lived-in lakeside apartment with weathered views'
    when 'vespormoor-university' then 'personal university flat or adult student room in the High Estate'
    when 'thornwood' then 'practical forest home near the public trails'
    when 'raven-ward' then 'sound-conscious modern apartment above Raven Ward'
    else 'private modern Vespormoor home' end,
  description=template.name||'''s home is a private, fully lived-in modern residence anchored in '||district.name||'. Old stone, dark timber, rain-muted windows, warm practical lamps, and contemporary furniture belong to ordinary present-day life rather than a historical set. The room reflects '||lower(template.occupation)||' and a few real interests—'||array_to_string(version.interests[1:4],', ')||'—without turning the home into a themed showroom.',
  prompt_text='Photorealistic contemporary interior of '||template.name||'''s private Vespormoor home in '||district.name||'. Preserve a coherent human-scale floor plan, old local architecture adapted for modern life, rain or mist outside believable windows, warm amber practical lighting, current furniture, phone chargers and ordinary personal objects, and specific evidence of a life as '||lower(template.occupation)||'. Personal details may reference '||array_to_string(version.interests[1:5],', ')||'. The interior is intimate and inhabited but not luxurious by default. Use contemporary clothing if the fictional adult character is present, with their separate canonical portrait/reference controlling face, body, heritage, and age. Do not use historical costume, visible monsters, creature anatomy, fantasy spectacle, generic castle bedrooms, public venue signage, or a reused district exterior.',
  canonical_visual_context=jsonb_build_object(
    'canonicalPrompt','Photorealistic contemporary private Vespormoor home for '||template.name||' in '||district.name||', grounded by old architecture, modern daily life, warm lamps, rain, and specific personal objects.',
    'indoorOutdoor','indoor','architecture',jsonb_build_array('adapted Vespormoor stone or timber','modern human-scale rooms','believable district-facing windows'),
    'lighting',jsonb_build_array('warm practical lamps','soft gray daylight or rainy-night reflections'),
    'recurringObjects',to_jsonb(version.interests[1:5]),
    'visualAnchors',jsonb_build_array('contemporary private residence',district.name,'lived-in occupation details','warm interior against cold wet streets'),
    'avoid',jsonb_build_array('historical costume default','visible monsters','creature anatomy','generic castle bedroom','public venue signage','reused district image'),
    'environmentReferencePolicy','text_only','promptVersion',2
  ),
  canonical_lore=jsonb_build_object(
    'version',2,'authored',true,
    'summary',template.name||'''s private modern home in '||district.name||'.',
    'atmosphere',jsonb_build_array('private','lived-in','warm against Vespormoor weather','contemporary'),
    'sensoryDetails',jsonb_build_array('rain softened beyond the windows','warm practical light','ordinary evidence of a recently occupied room'),
    'signatureDetails',to_jsonb(version.interests[1:3]),
    'layout',jsonb_build_array('coherent main living area','implied sleeping area','work or hobby corner'),
    'stableFacts',jsonb_build_array('This is '||template.name||'''s private home.','It is not a public map location.','Entry is permission-based.'),
    'localEtiquette',jsonb_build_array('Do not imply entry from remote chat alone.','Do not invent roommates, wealth, pets, or access.')
  ),
  reference_policy='text_only',source='authored',prompt_version=2,active=true,updated_at=now()
from public.together_character_versions version
join public.together_character_templates template on template.id=version.character_template_id
cross join public.together_locations district
where home.character_version_id=version.id and district.id=home.district_anchor_location_id
  and version.id::text like '23000000-0000-4000-8010-%';

-- Stable provider-neutral voice identity. xAI mappings use the current approved
-- built-in catalogue and never change between requests.
insert into public.together_character_voice_profiles(character_template_id,voice_key,characteristics,provider_mappings,metadata)
select template.id,'vespormoor-'||roster.slug,
  jsonb_build_object('gender',roster.gender,'warmth',version.personality_config->'warmth','energy',version.personality_config->'socialEnergy','expressiveness',version.personality_config->'spontaneity','delivery',roster.dialogue_tone),
  version.voice_config->'providerMappings',jsonb_build_object('derivedFromVersionId',version.id,'source','vespormoor_roster_v1')
from kivelle_vespormoor_roster roster
join public.together_character_templates template on template.id=('22000000-0000-4000-8010-'||lpad(roster.roster_id::text,12,'0'))::uuid
join public.together_character_versions version on version.id=('23000000-0000-4000-8010-'||lpad(roster.roster_id::text,12,'0'))::uuid
on conflict(character_template_id) do update set voice_key=excluded.voice_key,characteristics=excluded.characteristics,
  provider_mappings=excluded.provider_mappings,metadata=excluded.metadata,active=true,updated_at=now();

-- Reusable Life Engine activities add natural optional movement around the
-- authored weekly schedule rather than replacing it.
with activities(activity_key,title,category,start_minute,end_minute,frequency,maximum) as(values
  ('home_cooking','Making an ordinary meal at home','home',960,1260,1,3),
  ('quiet_home','Taking private time at home','home',1080,1410,2,5),
  ('vespormoor_errand','Handling an errand around Vesper Square','errand',600,1080,1,2)
)
insert into public.together_character_activity_templates(
  character_version_id,activity_key,title,category,valid_time_windows,duration_minutes,
  location_categories,location_slugs,tags,affinity,preferred_weekly_frequency,maximum_weekly_frequency,
  minimum_gap_hours,energy_requirement,social_requirement,priority,visibility,interruptibility,metadata
)
select version.id,activity_key,title,category,jsonb_build_array(jsonb_build_object('startMinute',start_minute,'endMinute',end_minute)),
  int4range(45,121,'[]'),array[category],case when activity_key='vespormoor_errand' then array['vesper-square']::text[] else array[]::text[] end,
  array[category,'vespormoor'],.7,int4range(frequency,frequency+2,'[]'),maximum,18,null,'either','recurring_routine','hidden','open',
  jsonb_build_object('source','vespormoor_character_roster','outcomeEligible',false)
from kivelle_vespormoor_roster roster
join public.together_character_versions version on version.id=('23000000-0000-4000-8010-'||lpad(roster.roster_id::text,12,'0'))::uuid
cross join activities
on conflict(character_version_id,activity_key) do update set title=excluded.title,valid_time_windows=excluded.valid_time_windows,
  duration_minutes=excluded.duration_minutes,location_slugs=excluded.location_slugs,tags=excluded.tags,
  affinity=excluded.affinity,preferred_weekly_frequency=excluded.preferred_weekly_frequency,
  maximum_weekly_frequency=excluded.maximum_weekly_frequency,metadata=excluded.metadata,updated_at=now();

insert into public.together_character_activity_templates(
  character_version_id,activity_key,title,category,valid_time_windows,duration_minutes,
  location_categories,location_slugs,tags,affinity,preferred_weekly_frequency,maximum_weekly_frequency,
  minimum_gap_hours,energy_requirement,social_requirement,priority,visibility,interruptibility,metadata
)
select version.id,'signature_activity',initcap(roster.leisure_activity),'personal','[{"startMinute":600,"endMinute":1380}]'::jsonb,
  int4range(60,181,'[]'),array[]::text[],array[roster.leisure_slug],roster.interests[1:3],.92,int4range(1,4,'[]'),4,20,null,'either',
  'preferred_activity','hint','open',jsonb_build_object('source','vespormoor_character_roster','activityLabel',roster.leisure_activity,'outcomeEligible',false)
from kivelle_vespormoor_roster roster
join public.together_character_versions version on version.id=('23000000-0000-4000-8010-'||lpad(roster.roster_id::text,12,'0'))::uuid
on conflict(character_version_id,activity_key) do update set title=excluded.title,location_slugs=excluded.location_slugs,tags=excluded.tags,
  metadata=excluded.metadata,updated_at=now();

do $$
declare roster_count int; version_count int; presence_count int; invalid_age_count int; invalid_place_count int;
begin
  select count(*),count(*) filter(where age<18) into roster_count,invalid_age_count from kivelle_vespormoor_roster;
  select count(*) into version_count from public.together_character_versions where id::text like '23000000-0000-4000-8010-%';
  select count(*) into presence_count from public.together_character_world_presence where world_id='10000000-0000-4000-8000-000000000010' and character_version_id::text like '23000000-0000-4000-8010-%';
  select count(*) into invalid_place_count from kivelle_vespormoor_roster roster
    where not exists(select 1 from public.together_locations location where location.world_id='10000000-0000-4000-8000-000000000010' and location.slug=roster.district_slug)
       or not exists(select 1 from public.together_locations location where location.world_id='10000000-0000-4000-8000-000000000010' and location.slug=roster.work_slug)
       or not exists(select 1 from public.together_locations location where location.world_id='10000000-0000-4000-8000-000000000010' and location.slug=roster.leisure_slug)
       or not exists(select 1 from public.together_locations location where location.world_id='10000000-0000-4000-8000-000000000010' and location.slug=roster.evening_slug)
       or not exists(select 1 from public.together_locations location where location.world_id='10000000-0000-4000-8000-000000000010' and location.slug=roster.weekend_slug);
  if roster_count<>45 or version_count<>45 or presence_count<>45 or invalid_age_count<>0 or invalid_place_count<>0 then
    raise exception 'Vespormoor roster validation failed: roster %, versions %, presence %, underage %, bad places %',roster_count,version_count,presence_count,invalid_age_count,invalid_place_count;
  end if;
end $$;

commit;
